import type { ChunkData, ChunkIterable } from "../../core/types.js";

type ResolvedChunkInput = ChunkIterable | (() => ChunkIterable);

type ChunkReader = {
  read(): Promise<{ readonly done: boolean; readonly value?: unknown }>;
  releaseLock?(): void;
};

type ReadableLike = {
  getReader(): ChunkReader;
};

function isAsyncIterable(value: unknown): value is AsyncIterable<ChunkData> {
  return (
    typeof value === "object" &&
    value !== null &&
    Symbol.asyncIterator in (value as Record<PropertyKey, unknown>)
  );
}

function isIterable(value: unknown): value is Iterable<ChunkData> {
  return (
    typeof value === "object" &&
    value !== null &&
    Symbol.iterator in (value as Record<PropertyKey, unknown>)
  );
}

function isReadableStream(value: unknown): value is ReadableLike {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as ReadableLike).getReader === "function"
  );
}

/** Resolves arrays, iterables, async iterables, streams and factories. */
export async function* iterateChunks(input: ResolvedChunkInput): AsyncGenerator<ChunkData> {
  const source = typeof input === "function" ? input() : input;

  if (isReadableStream(source)) {
    const reader = source.getReader();

    try {
      while (true) {
        const result = await reader.read();

        if (result.done) {
          return;
        }

        if (result.value !== undefined) {
          yield result.value as ChunkData;
        }
      }
    } finally {
      reader.releaseLock?.();
    }
  }

  if (isAsyncIterable(source)) {
    for await (const chunk of source) {
      yield chunk;
    }

    return;
  }

  if (isIterable(source)) {
    for (const chunk of source) {
      yield chunk;
    }
  }
}

/** Buffers an entire chunk source into one Blob. */
export async function collectChunks(
  input: ResolvedChunkInput,
  type: string,
  delay = 0,
): Promise<Blob> {
  const parts: BlobPart[] = [];

  for await (const chunk of iterateChunks(input)) {
    if (typeof chunk === "string" || chunk instanceof Blob || chunk instanceof ArrayBuffer) {
      parts.push(chunk);
    } else {
      const view = chunk as ArrayBufferView;
      const copy = new Uint8Array(view.byteLength);
      copy.set(new Uint8Array(view.buffer, view.byteOffset, view.byteLength));
      parts.push(copy);
    }

    if (delay > 0) {
      await new Promise<void>((resolve) => {
        setTimeout(resolve, delay);
      });
    }
  }

  return new Blob(parts, { type });
}

/** Converts a chunk to a BufferSource for MediaSource. */
export async function chunkToBufferSource(chunk: ChunkData): Promise<BufferSource> {
  if (typeof chunk === "string") {
    return new TextEncoder().encode(chunk);
  }

  if (chunk instanceof Blob) {
    return chunk.arrayBuffer();
  }

  if (chunk instanceof ArrayBuffer) {
    return chunk;
  }

  if (ArrayBuffer.isView(chunk)) {
    const copy = new Uint8Array(chunk.byteLength);
    copy.set(new Uint8Array(chunk.buffer, chunk.byteOffset, chunk.byteLength));
    return copy;
  }

  return new Uint8Array(0);
}

/** Small helper for tests and callers that need an ordered array. */
export async function collectChunkArray(input: ResolvedChunkInput): Promise<readonly ChunkData[]> {
  const result: ChunkData[] = [];

  for await (const chunk of iterateChunks(input)) {
    result.push(chunk);
  }

  return result;
}
